    Bug 1891713 - Fix copy behavior in message header fields. r=aleca

    Previously, right-clicking and copying a message header field without an
    active text selection relied on extracting DOM `.textContent`. Because
    modern header WebComponents include structural UI labels and hidden
    accessibility elements (e.g., screen-reader-only colons), copying the
    field would incorrectly include this extraneous text.

    This patch updates `gMessageHeader.copyString` to bypass the DOM when
    no specific text is highlighted. It now resolves the `data-header-name`
    and fetches the clean, raw string directly from the `currentHeaderData`
    representation. Manual text selections are still respected, and a fallback
    remains for custom headers not present in the data model.

    A new mochitest `test_copy_string_clean_value` is included to verify
    the pure string extraction logic.

    Differential Revision: https://phabricator.services.mozilla.com/D295481

diff --git a/mail/base/content/msgHdrView.js b/mail/base/content/msgHdrView.js
index ff3a568e317..31246b1066a 100644
--- a/mail/base/content/msgHdrView.js
+++ b/mail/base/content/msgHdrView.js
@@ -3331,11 +3331,29 @@ const gMessageHeader = {
     const target =
       event.currentTarget.parentNode.triggerNode ||
       event.currentTarget.parentNode.headerField;
-    navigator.clipboard.writeText(
-      window.getSelection().isCollapsed
-        ? target.textContent
-        : window.getSelection().toString()
-    );
+
+    // If the user actively highlighted something, honor their exact selection.
+    if (!window.getSelection().isCollapsed) {
+      navigator.clipboard.writeText(window.getSelection().toString());
+      return;
+    }
+
+    // Otherwise, find the data-header-name to look up the exact value.
+    const headerName =
+      target.dataset.headerName ||
+      target.closest("[data-header-name]")?.dataset.headerName;
+
+    let textToCopy = "";
+
+    if (headerName && currentHeaderData[headerName]) {
+      // Grab the exact value.
+      textToCopy = currentHeaderData[headerName].headerValue;
+    } else {
+      // Fallback for custom/edge-case UI elements not in the data model.
+      textToCopy = target.textContent;
+    }
+
+    navigator.clipboard.writeText(textToCopy.trim());
   },

   /**
